import{_ as l,o as a,c as r,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Rules","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/rules.md","filePath":"gameplay/rules.md","lastUpdated":1790774905000}'),i={name:"gameplay/rules.md"};function o(s,e,n,h,u,c){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>See the <a href="https://mcsrranked.com/guidelines" target="_blank" rel="noreferrer">Ranked Guidelines</a> for the rules/guidelines specific to playing ranked. <br> Besides the Ranked Guidelines, MCSR Ranked follows the SRC rules for Minecraft Any% Glitchless. This page is a summarization of the SRC rules and focuses on rules relevant to ranked. See <a href="https://mc.sr/rules" target="_blank" rel="noreferrer">mc.sr/rules</a> for the Official Rule Document.</p><h2 id="allowed-launchers" tabindex="-1">Allowed Launchers <a class="header-anchor" href="#allowed-launchers" aria-label="Permalink to &quot;Allowed Launchers&quot;">​</a></h2><ul><li><a href="https://mcsrranked.com/download" target="_blank" rel="noreferrer">Prism Launcher</a> (recommended)</li><li><a href="https://mcsrranked.com/download" target="_blank" rel="noreferrer">MultiMC</a></li><li><a href="https://mcsrlauncher.github.io/" target="_blank" rel="noreferrer">MCSR Launcher</a> (beta)</li><li><a href="https://modrinth.com/app" target="_blank" rel="noreferrer">Modrinth App</a></li><li><a href="https://atlauncher.com/" target="_blank" rel="noreferrer">ATLauncher</a></li><li><a href="https://www.minecraft.net/en-us/download" target="_blank" rel="noreferrer">Official Minecraft Launcher</a> (heavily discouraged)</li></ul><h2 id="rebind-rules" tabindex="-1">Rebind Rules <a class="header-anchor" href="#rebind-rules" aria-label="Permalink to &quot;Rebind Rules&quot;">​</a></h2><ul><li>Rebinding keys is legal, but <ul><li>Each game input may only have 1 key.</li><li>Each key may only cause 1 game input.</li><li>Keys must be rebound to buttons (e.g. binding to scrollwheel is not allowed).</li></ul></li><li>Left/right click must not be bound to a keyboard button to abuse repeated inputs.</li></ul><h2 id="macro-rules" tabindex="-1">Macro Rules <a class="header-anchor" href="#macro-rules" aria-label="Permalink to &quot;Macro Rules&quot;">​</a></h2><ul><li>Macros may resize the game window to any resolution as long as the game window stays within monitor bounds.</li><li>Macros may resize the game to 1 resolution outside monitor bounds (max. 16384 pixels in width or height).</li><li>Toggle sprint macros are allowed.</li><li>All other macros are not allowed.</li></ul><h2 id="external-resource-rules" tabindex="-1">External Resource Rules <a class="header-anchor" href="#external-resource-rules" aria-label="Permalink to &quot;External Resource Rules&quot;">​</a></h2><h3 id="legal-tools" tabindex="-1">Legal Tools <a class="header-anchor" href="#legal-tools" aria-label="Permalink to &quot;Legal Tools&quot;">​</a></h3><ul><li><a href="https://github.com/Ninjabrain1/Ninjabrain-Bot/releases/tag/1.5.2" target="_blank" rel="noreferrer">Ninjabrainbot</a> (<a href="https://youtu.be/l-q-_4R8_6M?t=713" target="_blank" rel="noreferrer">tutorial</a>)</li><li><a href="https://github.com/jojoe77777/Toolscreen/releases/latest" target="_blank" rel="noreferrer">Toolscreen</a> (<a href="https://youtu.be/YqS-fxPx_jo" target="_blank" rel="noreferrer">tutorial</a>)</li><li><a href="https://github.com/DuncanRuns/Jingle/releases#release-v1.3.0" target="_blank" rel="noreferrer">Jingle</a></li><li><a href="https://github.com/Slackow/SlackowWall/releases/tag/v1.4.9" target="_blank" rel="noreferrer">SlackowWall</a></li><li><a href="https://github.com/tesselslate/resetti" target="_blank" rel="noreferrer">Resetti</a></li><li><a href="https://tesselslate.github.io/waywall" target="_blank" rel="noreferrer">Waywall</a></li></ul><h2 id="glitches" tabindex="-1">Glitches <a class="header-anchor" href="#glitches" aria-label="Permalink to &quot;Glitches&quot;">​</a></h2><p>This list might be outdated, for the updated list on all allowed/disallowed glitches see Ruleset D of <a href="https://mc.sr/rules" target="_blank" rel="noreferrer">mc.sr/rules</a>.</p><h3 id="allowed-glitches" tabindex="-1">Allowed Glitches <a class="header-anchor" href="#allowed-glitches" aria-label="Permalink to &quot;Allowed Glitches&quot;">​</a></h3><ul><li>Pearl clipping</li><li>Seeing under water or lava using third person</li><li>Oneshot</li><li>Sticky boat clutch</li><li>Boat velocity reset</li><li>Boat breaking</li><li>Block effects being ignored on block edges</li><li>Statistics menu advancing</li><li>Soul skating</li><li>Placing doors inside the player</li><li>Continue sprinting while crawling or sneaking</li><li>Entering and breaking a boat simultaneously</li><li>Entering and breaking a nether portal simultaneously</li><li>Fast Looting</li><li>Altered Fast looting</li><li>Planar fog abuse</li><li>Ghost bucket</li></ul><h3 id="disallowed-glitches" tabindex="-1">Disallowed Glitches <a class="header-anchor" href="#disallowed-glitches" aria-label="Permalink to &quot;Disallowed Glitches&quot;">​</a></h3><ul><li>X-Ray</li><li>Shift clutch</li><li>Ghost scaffolding</li><li>Ghost blocks</li><li>Attribute swapping<br><br></li></ul><p>Reminder: these are not the full rules, but they should suffice for the average player.</p>',19)])])}const b=l(i,[["render",o]]);export{g as __pageData,b as default};
